#contact .mm-webforms__intro {
  margin: 0 0 1.1rem;
  color: var(--mm-contact-body);
  line-height: 1.65;
}
#contact .mm-webforms__notice {
  padding: 1rem 1.1rem;
  margin: 0.25rem 0 1.5rem;
  border-left: 4px solid var(--mm-contact-sage);
  border-radius: 0 0.55rem 0.55rem 0;
  background: var(--mm-contact-tint);
  color: var(--mm-contact-ink);
  font-size: 0.95rem;
  line-height: 1.6;
}
#contact .mm-webforms__notice strong {
  font-weight: 750;
}
#contact .mm-webforms {
  display: grid;
  gap: 1.1rem;
  margin-top: 1.35rem;
}
#contact .mm-webforms__field {
  display: grid;
  gap: 0.4rem;
}
#contact .mm-webforms__field label {
  color: var(--mm-contact-ink);
  font:
    700 0.96rem/1.4 "Source Sans 3",
    Arial,
    sans-serif;
}
#contact .mm-webforms .form-control {
  display: block;
  width: 100%;
  min-height: 48px;
  border: 1px solid #abbdb3;
  border-radius: 0.6rem;
  padding: 0.75rem 0.9rem;
  background: #fff;
  color: #283c46;
  font:
    400 1rem/1.5 "Source Sans 3",
    Arial,
    sans-serif;
  box-shadow: none;
}
#contact .mm-webforms textarea.form-control {
  min-height: 140px;
  resize: vertical;
}
#contact .mm-webforms .form-control:focus-visible {
  outline: 3px solid #526f61;
  outline-offset: 2px;
  border-color: #526f61;
  box-shadow: none;
}
#contact .mm-webforms__required {
  margin: -0.35rem 0 0;
  color: var(--mm-contact-body);
  font-size: 0.85rem;
}
#contact .mm-webforms__submit {
  justify-self: start;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.7rem;
  min-height: 50px;
  padding: 0.85rem 1.5rem;
  border: 2px solid var(--mm-contact-sage);
  border-radius: 999px;
  background: var(--mm-contact-sage);
  color: #fff;
  font:
    700 1.05rem/1.4 "Source Sans 3",
    Arial,
    sans-serif;
  text-align: center;
  cursor: pointer;
  transition:
    background-color 0.2s ease,
    border-color 0.2s ease;
}
#contact .mm-webforms__submit:hover {
  background: #405a4f;
  border-color: #405a4f;
}
#contact .mm-webforms__submit:focus-visible,
#contact .mm-webforms__phone a:focus-visible {
  outline: 3px solid #526f61;
  outline-offset: 4px;
}
#contact .mm-webforms__phone {
  margin: 1.4rem 0 0;
  color: var(--mm-contact-body);
}
#contact .mm-webforms__phone a {
  color: var(--mm-contact-link);
  font-weight: 700;
}
#contact .mm-webforms__honeypot {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  left: -10000px;
}
@media (prefers-reduced-motion: reduce) {
  #contact .mm-webforms__submit {
    transition: none;
  }
}

