document.addEventListener("DOMContentLoaded", function () {
  document
    .querySelectorAll("#team-therapist [data-mm-team-request]")
    .forEach(function (link) {
      link.addEventListener("click", function (event) {
        var contact = document.getElementById("request-appointment");
        var dialog = link.closest(".modal");
        if (
          !contact ||
          !dialog ||
          !window.bootstrap ||
          !window.bootstrap.Modal
        )
          return;
        event.preventDefault();
        dialog.addEventListener(
          "hidden.bs.modal",
          function () {
            window.location.hash = "request-appointment";
            contact.scrollIntoView({
              block: "start",
              behavior: "auto",
            });
            var heading = contact.querySelector("h2, h3");
            if (heading) {
              if (!heading.hasAttribute("tabindex"))
                heading.setAttribute("tabindex", "-1");
              heading.focus({ preventScroll: true });
            }
          },
          { once: true },
        );
        window.bootstrap.Modal.getOrCreateInstance(dialog).hide();
      });
    });
});

